/// Slot `slot` of `node`, a node of `kind` (checked in safety builds).
fn @"ir.at"(node: Sexp, comptime kind: Tag, comptime slot: usize, comptime what: []const u8) Sexp {
    @"ir.check"(node, kind, what);
    const items = node.items();
    return if (slot < items.len) items[slot] else .nil;
}

/// The children of `node` from `slot` on.
fn @"ir.restAt"(node: Sexp, comptime kind: Tag, comptime slot: usize, comptime what: []const u8) []const Sexp {
    @"ir.check"(node, kind, what);
    const items = node.items();
    return if (slot < items.len) items[slot..] else &.{};
}

fn @"ir.check"(node: Sexp, comptime kind: Tag, comptime what: []const u8) void {
    if (@import("builtin").optimize.runtimeSafety() and !node.isKind(kind)) {
        const actual = if (node.kind()) |k| @tagName(k) else @tagName(node);
        std.debug.panic(what ++ ": node is '{s}', not '" ++ @tagName(kind) ++ "'", .{actual});
    }
}


// =============================================================================
// Grammar
// =============================================================================

/// Node spans and rule ids are recorded (`@schema` or `--spans`).
pub const nodeStore = true;
/// Element extents are kept for side-band labels and nested nodes.
const elemEnds = true;
/// Lists keep trailing nils: positions are fixed by the schema.
const keepTrailingNils = true;
const hasTrivia = false;
const hasRepair = false;
/// `@as` groups the promotable token may become (see `promote`).
const asGroups = 0;
const numSymbols = 209;
const endSymbol: u16 = 1;
const errorSymbol: u16 = 2;

fn tokenToSymbol(token: Token) u16 {
    return switch (token.cat) {
        .@"eof" => 1,
        .@"newline" => 92,
        .@"indent" => 93,
        .@"outdent" => 94,
        .@"ident" => 96,
        .@"post_if" => 97,
        .@"const" => 99,
        .@"new" => 100,
        .@"drop_stmt" => 101,
        .@"pass" => 102,
        .@"return" => 103,
        .@"break" => 104,
        .@"continue" => 105,
        .@"defer" => 106,
        .@"errdefer" => 107,
        .@"raw" => 108,
        .@"pub" => 122,
        .@"use" => 123,
        .@"as" => 124,
        .@"fun" => 126,
        .@"sub" => 127,
        .@"from" => 130,
        .@"static" => 131,
        .@"kwarg_name" => 139,
        .@"enum" => 140,
        .@"error" => 141,
        .@"struct" => 142,
        .@"unique" => 143,
        .@"type" => 144,
        .@"drop" => 145,
        .@"test" => 146,
        .@"string_dq" => 147,
        .@"string_sq" => 148,
        .@"extern" => 149,
        .@"zig" => 150,
        .@"integer" => 155,
        .@"catch" => 160,
        .@"bar_capture" => 161,
        .@"ternary_if" => 162,
        .@"else" => 163,
        .@"nullish_jump" => 164,
        .@"or" => 165,
        .@"and" => 166,
        .@"not" => 167,
        .@"if" => 169,
        .@"while" => 170,
        .@"step_colon" => 171,
        .@"for" => 172,
        .@"in" => 173,
        .@"match" => 174,
        .@"true" => 177,
        .@"false" => 178,
        .@"bar_empty" => 179,
        .@"dotdot_open" => 180,
        .@"real" => 181,
        .@"of" => 183,
        .@"colon" => 95,
        .@"assign" => 98,
        .@"dot" => 125,
        .@"not_sym" => 128,
        .@"comma" => 132,
        .@"lparen" => 133,
        .@"rparen" => 134,
        .@"lbracket" => 135,
        .@"rbracket" => 136,
        .@"question" => 137,
        .@"lt" => 138,
        .@"star" => 153,
        .@"tilde" => 154,
        .@"minus" => 156,
        .@"plus" => 157,
        .@"slash" => 158,
        .@"percent" => 159,
        .@"at" => 182,
        .@"gt" => 197,
        .@"bar" => 201,
        .@"caret" => 202,
        .@"ampersand" => 203,
        .@"plus_assign" => 109,
        .@"minus_assign" => 110,
        .@"star_assign" => 111,
        .@"slash_assign" => 112,
        .@"percent_assign" => 113,
        .@"plus_wrap_assign" => 114,
        .@"minus_wrap_assign" => 115,
        .@"star_wrap_assign" => 116,
        .@"amp_assign" => 117,
        .@"bar_assign" => 118,
        .@"caret_assign" => 119,
        .@"lshift_assign" => 120,
        .@"rshift_assign" => 121,
        .@"arrow" => 129,
        .@"fat_arrow" => 175,
        .@"dotdot" => 176,
        .@"eq" => 195,
        .@"ne" => 196,
        .@"le" => 198,
        .@"ge" => 199,
        .@"nullish" => 200,
        .@"lshift" => 204,
        .@"rshift" => 205,
        .@"plus_wrap" => 206,
        .@"minus_wrap" => 207,
        .@"star_wrap" => 208,
        else => 2, // error
    };
}

fn promote(_: *BaseParser, _: Token) u16 {
    unreachable; // no @as group
}

fn executeAction(self: *BaseParser, ruleId: u16, pass: []Sexp) Sexp {
    return switch (ruleId) {
        0 => self.buildOf(&.{ .{ .tag = .@"module" } }, pass, .tree, false),
